/* getCscListTotalCount - kim.seong.ok */

SELECT

    COUNT(*)

FROM SBD200
    WHERE INST_NO = #{INST_NO}
    AND USER_ID = #{USER_ID}
    AND DEL_YN = 'N'



    AND CSC_NM LIKE '%'|| #{SEARCH_DATA} || '%'




    AND CSC_ESNTAL_NO LIKE '%'|| #{SEARCH_DATA} || '%'


/* selectCscAltmntRsvtList - kim.seong.ok */

SELECT
    B.*
    , DEC_B64(B.RSVCTM_NM_ENCPT) AS RSVCTM
    , TO_CHAR(TO_date(B.RSVT_YMD, 'YYYYMMDD'), 'dy') AS DAYOFWEEK
FROM
    SBD200 A
    JOIN SBD210 B ON A.INST_NO = B.INST_NO AND A.USER_ID = B.USER_ID AND A.CSC_ESNTAL_NO = B.CSC_ESNTAL_NO

WHERE A.INST_NO = #{INST_NO}
AND A.USER_ID = #{USER_ID}
AND B.DEL_YN = 'N'
AND B.RSVT_YMD = #{SEARCH_DATE}

/* selectDateWeeklyList - kim.seong.ok */
SELECT B.* , DEC_B64(B.RSVCTM_NM_ENCPT) AS RSVCTM , TO_CHAR(TO_date(B.RSVT_YMD, 'YYYYMMDD'), 'dy') AS DAYOFWEEK FROM SBD200 A JOIN SBD210 B ON A.INST_NO = B.INST_NO AND A.USER_ID = B.USER_ID AND A.CSC_ESNTAL_NO = B.CSC_ESNTAL_NO
WHERE A.INST_NO = #{INST_NO} AND A.USER_ID = #{USER_ID} AND B.DEL_YN = 'N' AND B.RSVT_YMD >= TO_CHAR(TO_DATE(#{SEARCH_DATE},'yyyymmdd') - TO_NUMBER(#{PREV_DAY}) ,'yyyymmdd') AND B.RSVT_YMD <= TO_CHAR(TO_DATE(#{SEARCH_DATE},'yyyymmdd') + TO_NUMBER(#{NEXT_DAY}) ,'yyyymmdd')


/* selectedCscAltmntRsvtSearchList - kim.seong.ok */

SELECT
    B.*
    , DEC_B64(B.RSVCTM_NM_ENCPT) AS RSVCTM
FROM
    SBD200 A
    JOIN SBD210 B ON A.INST_NO = B.INST_NO AND A.USER_ID = B.USER_ID AND A.CSC_ESNTAL_NO = B.CSC_ESNTAL_NO

WHERE A.INST_NO = #{INST_NO}
AND A.USER_ID = #{USER_ID}
AND B.CSC_ESNTAL_NO = #{CSC_ESNTAL_NO}
AND B.DEL_YN = 'N'
AND B.RSVT_YMD = #{SEARCH_DATE}

mapper.update:
/* updateCscDetail - kim.seong.ok */


UPDATE SBD200 SET

    CSC_NM        = #{CSC_NM},                                              /* 상담실명        */
    USE_YN        = #{USE_YN},                                              /* 사용여부       */
    LAST_MDFR_ID               = #{LAST_MDFR_ID},                                /* 최종수정자아이디        */
    LAST_MDFCN_DT              = SYSDATE                                    /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND USER_ID = #{USER_ID}
AND CSC_ESNTAL_NO = #{CSC_ESNTAL_NO}
AND DEL_YN = 'N'

/* deleteCscDetail - kim.seong.ok */


UPDATE SBD200 SET

    DEL_YN = 'Y',
    LAST_MDFR_ID               = #{LAST_MDFR_ID},                                /* 최종수정자아이디        */
    LAST_MDFCN_DT              = SYSDATE                                    /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND USER_ID = #{USER_ID}
AND CSC_ESNTAL_NO = #{CSC_ESNTAL_NO}

