mapper.insert:
SELECT NVL(MAX(INDEX_SN)+1 ,1) FROM SBD210
/* insertCscAltmntDetail - kim.seong.ok */
INSERT INTO SBD210 ( INST_NO /*기관번호 */ ,CSC_ESNTAL_NO /*상담실고유번호 */ ,INDEX_SN /*색인일련번호 */ ,TASKWK_SYS_SE_CD /*업무시스템구분코드 */ ,USER_ID /*사용자 아이디 */ ,CSC_NM /*상담실명 */ ,RSVT_YMD /*예약일자 */ ,RSVT_BGNG_HR /*예약시작시간 */ ,RSVT_END_HR /*예약종료시간 */ ,RSVCTM_ID /*예약자아이디 */ ,RSVCTM_NM_ENCPT /*예약자명암호화 */ ,RM_CN /*비고내용 */ ,REG_YMD /*등록일자 */ ,DEL_YN /*삭제여부 */ ,FRST_RGTR_ID /*최초등록자아이디 */ ,FRST_REG_DT /*최초등록일시 */ ,LAST_MDFR_ID /*최종수정자아이디 */ ,LAST_MDFCN_DT /*최종수정일시 */ ) VALUES ( #{INST_NO}, /*기관번호 */ #{CSC_ESNTAL_NO}, /*상담실고유번호 */ #{INDEX_SN}, /*색인일련번호 */ #{TASKWK_SYS_SE_CD}, /*업무시스템구분코드 */ #{USER_ID}, /*사용자 아이디 */ #{CSC_NM}, /*상담실명 */ #{RSVT_YMD}, /*예약일자 */ #{RSVT_BGNG_HR}, /*예약시작시간 */ #{RSVT_END_HR}, /*예약종료시간 */ #{RSVCTM_ID}, /*예약자아이디 */ ENC_B64(#{RSVCTM_NM_ENCPT}), /*예약자명암호화 */ #{RM_CN}, /*비고내용 */ #{REG_YMD}, /*등록일자 */ 'N', /*삭제여부 */ #{FRST_RGTR_ID}, /*최초등록자아이디 */ SYSDATE, /*최초등록일시 */ #{LAST_MDFR_ID}, /*최종수정자아이디 */ SYSDATE /*최종수정일시 */ )

mapper.update:
/* updateCscAltmntDetail - kim.seong.ok */


UPDATE SBD210 SET

    CSC_NM                      = #{CSC_NM}    /*상담실명          */
    ,RSVT_YMD                   = #{RSVT_YMD}    /*예약일자          */
    ,RSVT_BGNG_HR               = #{RSVT_BGNG_HR}    /*예약시작시간        */
    ,RSVT_END_HR                = #{RSVT_END_HR}    /*예약종료시간        */
    ,RSVCTM_ID                  = #{RSVCTM_ID}    /*예약자아이디        */
    ,RSVCTM_NM_ENCPT            = ENC_B64(#{RSVCTM_NM_ENCPT})    /*예약자명암호화       */
    ,RM_CN                      = #{RM_CN}    /*비고내용          */
    ,LAST_MDFR_ID               = #{LAST_MDFR_ID}    /* 최종수정자아이디        */
    ,LAST_MDFCN_DT              = SYSDATE       /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND USER_ID = #{USER_ID}
AND DEL_YN = 'N'
AND RSVT_YMD = #{RSVT_YMD}
AND RSVT_BGNG_HR = #{DPCN_CHECK_START_TIME}
AND CSC_ESNTAL_NO = #{CSC_ESNTAL_NO}
AND INDEX_SN = #{INDEX_SN}

/* deleteCscAltmntDetail - kim.seong.ok */


UPDATE SBD210 SET

    DEL_YN                      = 'Y'
    ,LAST_MDFR_ID               = #{LAST_MDFR_ID}    /* 최종수정자아이디        */
    ,LAST_MDFCN_DT              = SYSDATE       /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND USER_ID = #{USER_ID}
AND RSVT_YMD = #{RSVT_YMD}
AND RSVT_BGNG_HR = #{DPCN_CHECK_START_TIME}
AND CSC_ESNTAL_NO = #{CSC_ESNTAL_NO}
AND INDEX_SN = #{INDEX_SN}

